from pathlib import Path
ROOT=Path('/tmp/fridadev-m7-proof-20261007')
D=json.loads((ROOT/'authority.json').read_text())
def adapt(argv):
 return [s.replace('/tmp/fridadev-m6-aud03-proof-20261007',str(ROOT)).replace('fridadev-m6-aud03-proof','fridadev-m7-proof') for s in argv]
def record(label,argv):
 start=datetime.datetime.now(datetime.timezone.utc).isoformat();t=time.monotonic()
 p=subprocess.run(argv,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
 (ROOT/(label+'.log')).write_bytes(p.stdout);s=p.stdout.decode(errors='replace')
 r=dict(label=label,argv=argv,exit=p.returncode,started_utc=start,wall_seconds=round(time.monotonic()-t,3),log_sha256=hashlib.sha256(p.stdout).hexdigest(),log_bytes=len(p.stdout))
 if 'unittest' in argv:
  r['test_ids']=re.findall(r'^test\S* \(([^)]+)\) \.\.\. ',s,re.M)
  m=re.search(r'Ran (\d+) tests? in ([\d.]+)s',s);r['tests']=int(m[1]) if m else None
  for k in ('skipped','errors','failures'):
   m=re.search(k+r'=(\d+)',s[s.rfind('Ran '):]);r[k]=int(m[1]) if m else 0
 elif '--test' in argv:
  r['test_names']=re.findall(r'^# Subtest: (.*)$',s,re.M)
  for k in ('tests','pass','fail','skipped','cancelled'):
   m=re.search(r'^# '+k+r' (\d+)$',s,re.M);r[k]=int(m[1]) if m else None
 (ROOT/(label+'.json')).write_text(json.dumps(r,indent=2)+'\n')
 print(json.dumps({k:v for k,v in r.items() if k not in ('argv','test_ids','test_names')}),flush=True)
 if p.returncode:print(s[-3000:],flush=True)
 return p.returncode
def readiness(name):
 for _ in range(100):
  p=subprocess.run(['docker','exec',name,'pg_isready','-U','m1proof'],capture_output=True)
  if p.returncode==0:return
  time.sleep(.1)
 raise RuntimeError('SQL setup unavailable '+name)
def group(prefix,keys):
 for key in keys:
  if record(prefix+'-'+key,adapt(D['final']['selections'][key]['argv'])):return 1
 return 0
def native(prefix):
 (ROOT/'http-ready').unlink(missing_ok=True)
 record(prefix+'-http-start',adapt(D['isolation']['setup_records']['http-final-start']['argv']))
 for _ in range(200):
  if (ROOT/'http-ready').exists():break
  time.sleep(.05)
 else:raise RuntimeError('HTTP setup unavailable')
 record(prefix+'-http-ready',adapt(D['isolation']['setup_records']['http-final-readiness']['argv']))
 return group(prefix,['browser-native-http'])
if __name__=='__main__':
 mode=sys.argv[1];prefix=sys.argv[2] if len(sys.argv)>2 else 'before'
 if mode=='setup':
  for key in ('setup-pg','setup-vector','http-pg-start-good'):
   argv=adapt(D['isolation']['setup_records'][key]['argv'])
   for s in argv:
    if s.endswith(':/var/run/postgresql'):Path(s.split(':')[0]).mkdir(exist_ok=True)
   assert record(key,argv)==0;readiness(argv[argv.index('--name')+1])
 elif mode=='baseline':
  batches=[['final-baseline-python','final-new-python','lane-unit'],['final-baseline-node','final-baseline-chromium_historical','final-baseline-chromium_m4','final-new-browser','browser-simulated'],['final-baseline-sql','final-new-sql','product-sql','new-pause-sql'],['final-baseline-vector']]
  with concurrent.futures.ThreadPoolExecutor(4) as ex: results=list(ex.map(lambda keys:group(prefix,keys),batches))
  assert not any(results),results
  assert record(prefix+'-neighbors70',adapt(D['neighbors']['record']['argv']))==0
  assert native(prefix)==0
  for key,r in D['identifier_loading']['records'].items():assert record(prefix+'-collection-'+key,adapt(r['argv']))==0
 elif mode=='py':
  argv=adapt(D['final']['selections']['final-new-sql']['argv']);i=argv.index('python');argv=argv[:i]+['python',*sys.argv[3:]]
  sys.exit(record(prefix,argv))
 elif mode=='group':sys.exit(group(prefix,sys.argv[3:]))
 elif mode=='argv':sys.exit(record(prefix,json.loads(sys.argv[3])))

